INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Steht /24 für 24 Netzwerkbits?', 2, '[{"text": "Ja", "correct": true, "because": "CIDR zählt Netzwerkbits"}, {"text": "Nein", "correct": false, "because": "Korrekte Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske entspricht /16?', 3, '[{"text": "255.255.0.0", "correct": true, "because": "16 Bits gesetzt"}, {"text": "255.0.0.0", "correct": false, "because": "Nur 8 Bits"}, {"text": "255.255.255.0", "correct": false, "because": "24 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /24 bedeutet 255.255.255.0. b) CIDR ersetzt Klassen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) ist Maske, b) ist flexibler"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der CIDR-Notation?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert Maske"}, {"text": "Schrägstrich", "correct": false, "because": "Teil der Notation"}, {"text": "Farbcodierung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /8 eine Klasse-A-Maske ist?', 2, '[{"text": "Ja", "correct": true, "because": "8 Bits wie 255.0.0.0"}, {"text": "Nein", "correct": false, "because": "Passt zur Klasse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche CIDR-Notation passt zu 255.255.255.252?', 3, '[{"text": "/30", "correct": true, "because": "30 Bits gesetzt"}, {"text": "/24", "correct": false, "because": "Nur 24 Bits"}, {"text": "/32", "correct": false, "because": "Alle 32 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Masken sind CIDR-kompatibel?', 5, '[{"text": "/16", "correct": true, "because": "255.255.0.0"}, {"text": "/24", "correct": true, "because": "255.255.255.0"}, {"text": "/33", "correct": false, "because": "Über 32 Bits"}, {"text": "/15.5", "correct": false, "because": "Keine Dezimalwerte"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /24 hat 8 Hostbits. b) CIDR ist nur für IPv6. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CIDR auch für IPv4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für CIDR?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Kern der Notation"}, {"text": "Netzwerkadresse", "correct": false, "because": "Teil der Definition"}, {"text": "Betriebssystem", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist /32 eine Einzelhost-Maske?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Hostbits übrig"}, {"text": "Nein", "correct": false, "because": "Korrekte Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske entspricht /20?', 4, '[{"text": "255.255.240.0", "correct": true, "because": "20 Bits gesetzt"}, {"text": "255.255.255.0", "correct": false, "because": "24 Bits"}, {"text": "255.255.0.0", "correct": false, "because": "16 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /24 nur für kleine Netze ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel einsetzbar"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der CIDR-Definition?', 3, '[{"text": "Netzwerkbits", "correct": true, "because": "Bestimmen Maske"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /16 ist 255.255.0.0. b) CIDR erlaubt beliebige Bits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bits bis 32"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet CIDR?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Klassenlos"}, {"text": "Effizienz", "correct": true, "because": "Bessere Adressnutzung"}, {"text": "Schnellere Übertragung", "correct": false, "because": "Nicht relevant"}, {"text": "Einfache Lesbarkeit", "correct": false, "because": "Technisch komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei CIDR unwichtig?', 3, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert Maske"}, {"text": "Schrägstrich", "correct": false, "because": "Teil der Notation"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /24 256 Adressen?', 3, '[{"text": "Ja", "correct": true, "because": "2^8 Hostbits"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /0 eine gültige Maske ist?', 2, '[{"text": "Ja", "correct": true, "because": "0 Bits, gesamtes Internet"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche CIDR-Notation hat keine Hostbits?', 4, '[{"text": "/32", "correct": true, "because": "Alle Bits Netzwerk"}, {"text": "/24", "correct": false, "because": "8 Hostbits"}, {"text": "/16", "correct": false, "because": "16 Hostbits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske ist /28?', 3, '[{"text": "255.255.255.240", "correct": true, "because": "28 Bits gesetzt"}, {"text": "255.255.255.0", "correct": false, "because": "24 Bits"}, {"text": "255.255.0.0", "correct": false, "because": "16 Bits"}]');
